modelica_source:
model Baseline
  extends Modelica.Clocked.Examples.SimpleControlledDrive.Continuous;
end Baseline;
model BUG002
  extends Modelica.Clocked.Examples.SimpleControlledDrive.Continuous(load(J=0));
end BUG002;
model FinalBUG002
  extends Modelica.Clocked.Examples.SimpleControlledDrive.Continuous(load(final J=0));
end FinalBUG002;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG002\n");
simulate(BUG002, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG002\n");
simulate(FinalBUG002, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG002\n");
system("./Baseline -override load.J=0 -r=BUG002_override.csv");
